describe('Payment Timeout Error Handling', () => {
  beforeEach(() => {
    cy.visit('/checkout');
    cy.get('[data-testid="payment-form"]').should('be.visible');
  });

  it('should redirect to error page when payment times out', () => {
    cy.intercept('POST', '/api/payment/process', (req) => {
      req.destroy();
    }).as('paymentTimeout');

    cy.get('[data-testid="card-number"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date"]').type('12/25');
    cy.get('[data-testid="cvv"]').type('123');
    cy.get('[data-testid="submit-payment"]').click();

    cy.wait('@paymentTimeout', { timeout: 15000 }).then(() => {
      cy.url().should('include', '/error');
      cy.get('[data-testid="error-message"]').should('contain', 'Payment timeout');
      cy.get('[data-testid="error-code"]').should('contain', 'TIMEOUT');
    });
  });

  it('should display timeout error message and retry button on error page', () => {
    cy.intercept('POST', '/api/payment/process', (req) => {
      req.reply({
        statusCode: 504,
        body: { error: 'Gateway Timeout', code: 'PAYMENT_TIMEOUT' },
        delay: 30000
      });
    }).as('paymentGatewayTimeout');

    cy.get('[data-testid="card-number"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date"]').type('12/25');
    cy.get('[data-testid="cvv"]').type('123');
    cy.get('[data-testid="submit-payment"]').click();

    cy.wait('@paymentGatewayTimeout', { timeout: 35000 });

    cy.url().should('include', '/error');
    cy.get('[data-testid="error-title"]').should('be.visible').and('contain', 'Payment Failed');
    cy.get('[data-testid="error-description"]').should('contain', 'timeout');
    cy.get('[data-testid="retry-button"]').should('be.visible').and('be.enabled');
    cy.get('[data-testid="return-home-button"]').should('be.visible');
  });

  it('should allow user to retry payment after timeout', () => {
    cy.intercept('POST', '/api/payment/process', (req) => {
      req.destroy();
    }).as('firstPaymentAttempt');

    cy.get('[data-testid="card-number"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date"]').type('12/25');
    cy.get('[data-testid="cvv"]').type('123');
    cy.get('[data-testid="submit-payment"]').click();

    cy.wait('@firstPaymentAttempt', { timeout: 15000 });
    cy.url().should('include', '/error');

    cy.intercept('POST', '/api/payment/process', (req) => {
      req.reply({
        statusCode: 200,
        body: { success: true, transactionId: 'TXN123456' }
      });
    }).as('retryPayment');

    cy.get('[data-testid="retry-button"]').click();
    cy.wait('@retryPayment');

    cy.url().should('include', '/success');
    cy.get('[data-testid="success-message"]').should('contain', 'Payment successful');
  });

  it('should handle multiple consecutive timeouts gracefully', () => {
    let attemptCount = 0;

    cy.intercept('POST', '/api/payment/process', (req) => {
      attemptCount++;
      if (attemptCount < 3) {
        req.destroy();
      } else {
        req.reply({
          statusCode: 200,
          body: { success: true, transactionId: 'TXN789012' }
        });
      }
    }).as('paymentWithRetries');

    cy.get('[data-testid="card-number"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date"]').type('12/25');
    cy.get('[data-testid="cvv"]').type('123');
    cy.get('[data-testid="submit-payment"]').click();

    cy.wait('@paymentWithRetries', { timeout: 15000 });
    cy.url().should('include', '/error');

    cy.get('[data-testid="retry-button"]').click();
    cy.wait('@paymentWithRetries', { timeout: 15000 });
    cy.url().should('include', '/error');

    cy.get('[data-testid="retry-button"]').click();
    cy.wait('@paymentWithRetries');

    cy.url().should('include', '/success');
    cy.get('[data-testid="transaction-id"]').should('contain', 'TXN789012');
  });
});
